	}

	if vCaller != g.white && vCaller != g.black {
		return errors.New("hanya pemain dalam game ini yang dapat menyerah")
	}

	g.resignedBy = vCaller
	if vCaller == g.white {
		g.status = "BLACK_WON"
	} else {
		g.status = "WHITE_WON"
	}

	g.settledBy = vCaller
	g.drawOfferedBy = ""
	g.turnDeadline = 0
	g.turnChallengedBy = ""
	g.challengeDeadline = 0
	return nil
}

